// BaseCheckboxEl is gpui_kit::base::Checkbox.
type CheckboxEl struct{ rt.ElAnimatableElement }

// Creates an unchecked checkbox with a stable element identifier.
//
// BaseCheckbox is <gpui_kit::base::Checkbox>::new.
func Checkbox(id gk.ID, st ...gk.Style) CheckboxEl {
	rt.UseBaseCheckbox()
	n := rt.NewNode(293)
	o := rt.NodeArgs(n)
	rt.PutID(o, id)
	rt.Tokens(n, st)
	return CheckboxEl{ElAnimatableElement: rt.MkElAnimatableElement(n)}
}

// Sets the label exposed to accessibility clients.
//
// A checkbox without text children has no accessible name, so set this whenever it is drawn
// without visible text.
//
